        n = load(f'model.language_model.layers.{L}.linear_attn.norm.weight').float().numpy()
        z = load(f'model.language_model.layers.{L}.linear_attn.in_proj_z.weight').float().numpy()
        o = load(f'model.language_model.layers.{L}.linear_attn.out_proj.weight').float().numpy()
